def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 2:
        return 'C'

    opp_defects = 0
    my_defects = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1

    last_my, last_opp = history[-1]

    if n >= 90:
        if my_defects == 0:
            if n == 90:
                return 'D'
            else:
                return 'C'
        else:
            if opp_defects == 0:
                return 'D'

    if n == 99:
        return 'D'

    if last_opp == 'D':
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    else:
        return 'C'
